WITH parsed AS (SELECT id, effective_from, discounts, AGGREGATE(tier_prices, CAST(0 AS DOUBLE), (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, SLICE(tier_limits, 1, 2) AS first_two_limits, ELEMENT_AT(tier_prices, 1) AS entry_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps FROM price_tiers WHERE effective_from >= '2024-10-05') SELECT DATE_TRUNC('YEAR', effective_from) AS year_start, DATE_TRUNC('WEEK', effective_from) AS week_start, APPROX_PERCENTILE(entry_price, 0.5) AS entry_price_p50, COUNT(DISTINCT id) AS distinct_ids, COUNT(DISTINCT id) AS distinct_ids_2 FROM parsed GROUP BY GROUPING SETS ((DATE_TRUNC('YEAR', effective_from), DATE_TRUNC('WEEK', effective_from)), (DATE_TRUNC('YEAR', effective_from)), ()) ORDER BY distinct_ids_2 DESC;
